#!/usr/bin/env bash
# Derive the broker-free catalogue CI entrypoint from the production release workflow.
# Pull-request CI may not grant id-token: write (.github/tests/test-ci-idtoken-boundary.sh), and
# GitHub refuses a call whose caller grants less than a called job asks for, even when that job
# never runs. So catalogue CI calls this projection instead: production, with only its display
# name changed and the release job's permissions emptied. Its offline-test and egress-probe jobs
# are exactly production's, and its release job can never reach the GitHub token broker.
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
source="${1:-$root/.github/workflows/create-release.yaml}"
destination="${2:-$root/.github/workflows/create-release-offline.yaml}"
work="$(mktemp)"
trap 'rm -f "$work"' EXIT
yq '
  .name = "🎉 Create Release (Offline CI)" |
  del(.jobs.release.permissions) |
  .jobs.release.permissions = {}
' "$source" >"$work"
{
  printf '# Generated by .github/scripts/generate-create-release-offline.sh; do not edit.\n'
  cat "$work"
} >"$destination"
